import { Pool } from 'pg';
import { pgPoolOptions } from '@/lib/db/pg-options';
import { notFound } from 'next/navigation';
import { VerifiedFanForm } from './VerifiedFanForm';

interface EventRow {
  id: string;
  title: string;
  date_start: string;
  verified_fan_enabled: boolean;
  verified_fan_presale_starts_at: string | null;
  verified_fan_presale_ends_at: string | null;
  promoter_name: string | null;
  brand_color_hex: string | null;
}

async function fetchEvent(id: string): Promise<EventRow | null> {
  if (!/^[0-9a-f-]{36}$/i.test(id)) return null;
  const db = new Pool(pgPoolOptions(process.env.DATABASE_URL));
  try {
    const r = await db.query<EventRow>(
      `SELECT e.id, e.title, e.date_start::text,
              e.verified_fan_enabled,
              e.verified_fan_presale_starts_at::text,
              e.verified_fan_presale_ends_at::text,
              p.name AS promoter_name, p.brand_color_hex
         FROM catalog.events e
         LEFT JOIN platform.promoters p ON p.id = e.promoter_id
        WHERE e.id = $1`,
      [id],
    );
    return r.rows[0] ?? null;
  } finally {
    await db.end();
  }
}

export const dynamic = 'force-dynamic';

export default async function VerifiedFanRegisterPage({
  params,
}: {
  params: { locale: string; id: string };
}) {
  const event = await fetchEvent(params.id);
  if (!event) notFound();
  if (!event.verified_fan_enabled) {
    return (
      <div className="container mx-auto max-w-2xl px-4 py-10">
        <h1 className="text-2xl font-bold">{event.title}</h1>
        <p className="mt-4 text-sm text-muted-foreground">
          Tato akce nemá Verified Fan registraci. Vstupenky budou v běžném prodeji.
        </p>
      </div>
    );
  }

  const brand =
    event.brand_color_hex && /^#[0-9a-f]{6}$/i.test(event.brand_color_hex)
      ? event.brand_color_hex
      : '#10b981';

  const presaleStart = event.verified_fan_presale_starts_at
    ? new Date(event.verified_fan_presale_starts_at)
    : null;
  const presaleEnd = event.verified_fan_presale_ends_at
    ? new Date(event.verified_fan_presale_ends_at)
    : null;
  const now = new Date();
  const presaleActive =
    presaleStart && presaleEnd && now >= presaleStart && now <= presaleEnd;
  const registrationClosed = presaleEnd && now > presaleEnd;

  return (
    <div className="container mx-auto max-w-2xl px-4 py-10">
      <div
        className="rounded-lg p-8 text-white"
        style={{ background: `linear-gradient(135deg, ${brand} 0%, ${brand}dd 100%)` }}
      >
        <p className="text-sm font-medium uppercase tracking-wider opacity-90">
          ⭐ Verified Fan registrace
        </p>
        <h1 className="mt-2 text-3xl font-bold">{event.title}</h1>
        <p className="mt-2 text-sm opacity-90">{event.promoter_name}</p>
      </div>

      <div className="mt-6 rounded-lg border bg-card p-6 space-y-4">
        <div>
          <h2 className="text-lg font-semibold">Jak to funguje</h2>
          <ol className="mt-2 list-decimal pl-5 text-sm text-muted-foreground space-y-1">
            <li>Zaregistruj se jako fanoušek (ověříme, že nejsi bot)</li>
            <li>Vyberemě fanoušky, kteří dostanou unikátní presale kód</li>
            <li>Klíčový pravidlo: <strong>registrace ≠ garance</strong>. Je to filtr proti
                botům a překupníkům, ne fronta s jistotou.</li>
            <li>Pokud budeš vybrán, dostaneš email s kódem před oficiálním onsale</li>
          </ol>
        </div>

        {registrationClosed ? (
          <div className="rounded-md border border-amber-300 bg-amber-50 p-3 text-sm text-amber-900">
            ⏰ Registrace je už uzavřená. Vstupenky budou v běžném prodeji.
          </div>
        ) : presaleActive ? (
          <VerifiedFanForm eventId={event.id} brandColor={brand} />
        ) : presaleStart ? (
          <div className="rounded-md border border-blue-300 bg-blue-50 p-3 text-sm text-blue-900">
            Registrace začne {presaleStart.toLocaleString('cs-CZ', { day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' })}.
          </div>
        ) : (
          <VerifiedFanForm eventId={event.id} brandColor={brand} />
        )}
      </div>

      <p className="mt-4 text-xs text-center text-muted-foreground">
        Pravidla viz <a href="/cs/legal/verified-fan-terms" className="underline">Podmínky Verified Fan programu</a>
      </p>
    </div>
  );
}

/**
 * /cs/p/[slug] — public profil promotéra (sdílecí stránka divadla / klubu)
 *
 * Ukazuje branding (logo, barva, tagline) + list všech aktuálních published akcí.
 * Slug = `platform.promoters.slug`. URL ke sdílení na sociálních sítích
 * a embedu do vlastní stránky divadla.
 */

import type { Metadata } from 'next';
import Link from 'next/link';
import { notFound, redirect } from 'next/navigation';
import { Pool } from 'pg';
import { Card, CardContent } from '@/components/ui/card';
import { pgPoolOptions } from '@/lib/db/pg-options';
import { launchFeatureEnabled } from '@/lib/features/launch-flags';
import { formatDate } from '@/lib/format';
import { isValidLocale, DEFAULT_LOCALE } from '@/lib/i18n';
import { FollowButton } from './FollowButton';

const BASE_URL = process.env.NEXT_PUBLIC_APP_URL ?? 'http://localhost:3000';

interface PromoterRow {
  id: string;
  name: string;
  slug: string;
  contact_email: string | null;
  brand_color_hex: string | null;
  brand_logo_url: string | null;
  brand_tagline: string | null;
}

interface EventRow {
  id: string;
  slug: string | null;
  title: string;
  date_start: string;
  category: string | null;
  venue_name: string | null;
  city: string | null;
  min_price: number | null;
  currency: string;
  cover_image: string | null;
}

interface PromoterStats {
  total_events: string;
  upcoming_events: string;
  past_events: string;
  avg_rating: number | null;
  review_count: string;
}

function shadeColor(hex: string, percent: number): string {
  const m = /^#([0-9a-f]{6})$/i.exec(hex);
  if (!m) return hex;
  const num = parseInt(m[1], 16);
  let r = (num >> 16) & 0xff;
  let g = (num >> 8) & 0xff;
  let b = num & 0xff;
  const factor = 1 + percent / 100;
  r = Math.min(255, Math.max(0, Math.round(r * factor)));
  g = Math.min(255, Math.max(0, Math.round(g * factor)));
  b = Math.min(255, Math.max(0, Math.round(b * factor)));
  return `#${((r << 16) | (g << 8) | b).toString(16).padStart(6, '0')}`;
}

async function fetchPromoter(slug: string): Promise<{
  promoter: PromoterRow;
  events: EventRow[];
  stats: PromoterStats;
} | null> {
  const db = new Pool(pgPoolOptions(process.env.DATABASE_URL));
  try {
    const pRes = await db.query<PromoterRow>(
      `SELECT id, name, slug, contact_email, brand_color_hex, brand_logo_url, brand_tagline
       FROM platform.promoters
       WHERE slug = $1 AND status = 'active'`,
      [slug],
    );
    if (pRes.rows.length === 0) return null;
    const promoter = pRes.rows[0];

    const [eRes, sRes] = await Promise.all([
      db.query<EventRow>(
        `SELECT e.id, e.slug, e.title, e.date_start, e.category, e.currency,
                e.cover_image_url AS cover_image,
                v.name AS venue_name, v.city,
                (SELECT MIN(base_price) FROM catalog.ticket_types WHERE event_id = e.id) AS min_price
         FROM catalog.events e
         LEFT JOIN catalog.venues v ON v.id = e.venue_id
         WHERE e.promoter_id = $1
           AND e.status = 'published'
           AND e.date_start > now() - interval '6 hours'
         ORDER BY e.date_start ASC
         LIMIT 50`,
        [promoter.id],
      ),
      db.query<PromoterStats>(
        `SELECT
           COUNT(*) FILTER (WHERE status IN ('published','finished'))::text AS total_events,
           COUNT(*) FILTER (WHERE status = 'published' AND date_start > now())::text AS upcoming_events,
           COUNT(*) FILTER (WHERE date_start < now())::text AS past_events,
           (SELECT AVG(rating)::numeric(3,2)
              FROM marketing.event_reviews er
              JOIN catalog.events e2 ON e2.id = er.event_id
              WHERE e2.promoter_id = $1 AND er.status = 'published') AS avg_rating,
           (SELECT COUNT(*)::text
              FROM marketing.event_reviews er
              JOIN catalog.events e2 ON e2.id = er.event_id
              WHERE e2.promoter_id = $1 AND er.status = 'published') AS review_count
         FROM catalog.events
         WHERE promoter_id = $1`,
        [promoter.id],
      ).catch(() => ({
        rows: [
          {
            total_events: '0',
            upcoming_events: '0',
            past_events: '0',
            avg_rating: null,
            review_count: '0',
          },
        ],
      })),
    ]);

    return {
      promoter,
      events: eRes.rows,
      stats: sRes.rows[0] ?? {
        total_events: '0',
        upcoming_events: '0',
        past_events: '0',
        avg_rating: null,
        review_count: '0',
      },
    };
  } finally {
    await db.end();
  }
}

export async function generateMetadata({
  params,
}: {
  params: { locale: string; slug: string };
}): Promise<Metadata> {
  const data = await fetchPromoter(params.slug);
  if (!data) return { title: 'Tixly' };
  const title = `${data.promoter.name} — vstupenky online`;
  const description =
    data.promoter.brand_tagline ??
