  return {
    title,
    description,
    alternates: { canonical: `${BASE_URL}/${params.locale}/p/${params.slug}` },
    openGraph: {
      title,
      description,
      siteName: 'Tixly',
      url: `${BASE_URL}/${params.locale}/p/${params.slug}`,
    },
  };
}

